import { MakeLogicType, actions, connect, kea, listeners, path, reducers, selectors } from 'kea'

import { commandLogic } from 'lib/components/Command/commandLogic'
import posthog from 'lib/posthog-typed'
import { userLogic } from 'scenes/userLogic'

import { UserType } from '~/types'

import type { CommandOpenSource } from '../Command/commandLogic'
import { IN_APP_ONBOARDING_FLOWS, InAppOnboardingFlow, InAppOnboardingSignal } from './inAppOnboardingFlows'
import { INITIAL_PROGRESS, InAppOnboardingProgress, advanceProgress, isFlowComplete } from './inAppOnboardingProgress'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface inAppOnboardingLogicValues {
    user: UserType | null // userLogic
    activeFlow: InAppOnboardingFlow | null
    activeProgress: InAppOnboardingProgress
    closedFlowKeys: string[]
    completedFlowKeys: string[]
    isActiveFlowComplete: boolean
    progressByFlow: Record<string, InAppOnboardingProgress>
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface inAppOnboardingLogicActions {
    updateHasSeenProductIntroFor: (
        productKey: string,
        value?: boolean | undefined
    ) => {
        productKey: string
        value: boolean
    } // userLogic
    closeFlow: (flowKey: string) => {
        flowKey: string
    }
    completeFlow: (flowKey: string) => {
        flowKey: string
    }
    recordSignal: (signal: InAppOnboardingSignal) => {
        signal: InAppOnboardingSignal
    }
    reportFlowShown: (flowKey: string) => {
        flowKey: string
    }
    setProgress: (
        flowKey: string,
        progress: InAppOnboardingProgress
    ) => {
        flowKey: string
        progress: InAppOnboardingProgress
    }
    skipFlow: (flowKey: string) => {
        flowKey: string
    }
}

export type inAppOnboardingLogicType = MakeLogicType<inAppOnboardingLogicValues, inAppOnboardingLogicActions>

/** Runs the in-app onboarding flows: picks the one to show, moves it on as the user does each step,
 * and records finishing or skipping it against the user so it shows once. */
export const inAppOnboardingLogic = kea<inAppOnboardingLogicType>([
    path(['lib', 'components', 'InAppOnboarding', 'inAppOnboardingLogic']),
    connect(() => ({
        values: [userLogic, ['user']],
        actions: [userLogic, ['updateHasSeenProductIntroFor']],
    })),
    actions({
        recordSignal: (signal: InAppOnboardingSignal) => ({ signal }),
        setProgress: (flowKey: string, progress: InAppOnboardingProgress) => ({ flowKey, progress }),
        completeFlow: (flowKey: string) => ({ flowKey }),
        skipFlow: (flowKey: string) => ({ flowKey }),
        closeFlow: (flowKey: string) => ({ flowKey }),
        reportFlowShown: (flowKey: string) => ({ flowKey }),
    }),
    reducers({
        // Kept across reloads, so a refresh mid-flow picks up at the same step.
        progressByFlow: [
            {} as Record<string, InAppOnboardingProgress>,
            { persist: true },
            {
                setProgress: (state, { flowKey, progress }) => ({ ...state, [flowKey]: progress }),
                closeFlow: (state, { flowKey }) => {
                    const { [flowKey]: _, ...rest } = state
                    return rest
                },
            },
        ],
        // Marking a flow seen reloads the user, and the finished card has to outlast that.
        completedFlowKeys: [
            [] as string[],
            {
                completeFlow: (state, { flowKey }) => [...state, flowKey],
            },
        ],
        // Hides a flow at once, before the reloaded user says it was seen.
        closedFlowKeys: [
            [] as string[],
            {
                closeFlow: (state, { flowKey }) => [...state, flowKey],
            },
        ],
    }),
    selectors({
        activeFlow: [
            (s) => [s.user, s.closedFlowKeys, s.completedFlowKeys],
            (user, closedFlowKeys, completedFlowKeys): InAppOnboardingFlow | null => {
                // An unloaded user is not a user who has seen nothing, so nothing shows until it arrives.
                if (!user) {
                    return null
                }
                return (
                    IN_APP_ONBOARDING_FLOWS.find(
                        (flow) =>
                            !closedFlowKeys.includes(flow.key) &&
                            (completedFlowKeys.includes(flow.key) || !user.has_seen_product_intro_for?.[flow.seenKey])
                    ) ?? null
                )
            },
        ],
        activeProgress: [
            (s) => [s.activeFlow, s.progressByFlow],
            (activeFlow, progressByFlow): InAppOnboardingProgress =>
                (activeFlow && progressByFlow[activeFlow.key]) || INITIAL_PROGRESS,
        ],
        isActiveFlowComplete: [
            (s) => [s.activeFlow, s.activeProgress],
            (activeFlow, activeProgress): boolean => !!activeFlow && isFlowComplete(activeFlow, activeProgress),
        ],
    }),
    listeners(({ actions, values }) => ({
        [commandLogic.actionTypes.openCommand]: ({ source }: { source: CommandOpenSource }) => {
            // Only the shortcut counts: the point is to press it, not to click the search button.
            if (source === 'keyboard-shortcut') {
                actions.recordSignal('command-opened-by-keyboard')
            }
        },
        [commandLogic.actionTypes.closeCommand]: () => {
            actions.recordSignal('command-closed')
        },
        recordSignal: ({ signal }) => {
            const flow = values.activeFlow
            if (!flow || values.isActiveFlowComplete) {
                return
            }
            const progress = values.activeProgress
            const next = advanceProgress(flow, progress, signal)
            if (next === progress) {
                return
            }
            actions.setProgress(flow.key, next)
            if (next.stepIndex === progress.stepIndex) {
                return
            }
            posthog.capture('in app onboarding step completed', {
                flow: flow.key,
                step: flow.steps[progress.stepIndex].key,
                step_index: progress.stepIndex,
                step_count: flow.steps.length,
            })
            if (isFlowComplete(flow, next)) {
                actions.completeFlow(flow.key)
            }
        },
        completeFlow: ({ flowKey }) => {
            const flow = IN_APP_ONBOARDING_FLOWS.find((candidate) => candidate.key === flowKey)
            posthog.capture('in app onboarding completed', { flow: flowKey })
            // Recorded on finishing the last step rather than on closing the card, so a reload never repeats it.
            if (flow) {
                actions.updateHasSeenProductIntroFor(flow.seenKey)
            }
        },
        skipFlow: ({ flowKey }) => {
            const flow = values.activeFlow
            if (flow?.key === flowKey) {
                const progress = values.activeProgress
                posthog.capture('in app onboarding skipped', {
                    flow: flowKey,
                    step: flow.steps[progress.stepIndex]?.key ?? null,
                    step_index: progress.stepIndex,
                    step_count: flow.steps.length,
                })
            }
            actions.closeFlow(flowKey)
        },
        closeFlow: ({ flowKey }) => {
            const flow = IN_APP_ONBOARDING_FLOWS.find((candidate) => candidate.key === flowKey)
            // Also on finishing, in case the write when the last step completed did not land.
            if (flow) {
                actions.updateHasSeenProductIntroFor(flow.seenKey)
            }
        },
        reportFlowShown: ({ flowKey }) => {
            posthog.capture('in app onboarding shown', { flow: flowKey })
        },
    })),
])
